    @Test
    fun accountApiKeyOmitsDefaultStore() {
        val requests = mutableListOf<Request>()
        val http =
            OkHttpClient.Builder()
                .addInterceptor { chain ->
                    val request = chain.request()
                    requests += request
                    Response.Builder()
                        .request(request)
                        .protocol(Protocol.HTTP_1_1)
                        .code(200)
                        .message("OK")
                        .body("{}".toResponseBody())
                        .build()
                }
                .build()
        val client =
            SellApp(
                apiKey = "account-key",
                store = "configured-store",
                httpClient = http,
                maxRetries = 0,
            )
        for (path in listOf("/v2/me", "/v2/stores", "/v2/stores/12")) {
            client.request("GET", path)
            assertEquals("Bearer account-key", requests.last().header("Authorization"))
            assertNull(requests.last().header("X-STORE"))
        }
        client.request("GET", "/v2/products")
        assertEquals("configured-store", requests.last().header("X-STORE"))
        assertEquals(4, requests.size)
        http.dispatcher.executorService.shutdown()
        http.connectionPool.evictAll()
    }

    @Test
