        var calls = 0
        val http =
            OkHttpClient.Builder()
                .addInterceptor { chain ->
                    calls++
                    val json = calls == 2
                    val text =
                        if (calls == 3) ""
                        else if (json)
                            com.fasterxml.jackson.module.kotlin
                                .jacksonObjectMapper()
                                .writeValueAsString(html)
                        else html
                    Response.Builder()
                        .request(chain.request())
                        .protocol(Protocol.HTTP_1_1)
                        .code(if (calls == 3) 302 else 200)
                        .message("test")
                        .header(
                            "Content-Type",
                            if (json) "application/json" else "text/html; charset=utf-8",
                        )
                        .header("X-Request-ID", "html-request")
                        .header("Location", "https://example.invalid/callback")
                        .body(text.toResponseBody())
                        .build()
                }
                .build()
        val client = SellApp(httpClient = http)
        fun response() =
            client.oauth.getAuthorizationRequestWithResponse(
                "code",
                "client",
                "https://example.invalid/callback",
                "state",
                "a".repeat(43),
                "S256",
            )
        val first = response()
        assertEquals(html, first.value)
        assertEquals(html, first.rawBody)
        assertEquals(200, first.status)
        assertEquals(html, response().value)
        val redirect = response()
        assertEquals(302, redirect.status)
        assertEquals("", redirect.value)
        assertEquals(listOf("https://example.invalid/callback"), redirect.headers["Location"])
